import{_ as d,a0 as o,w as r,s as p,I as s,x as i,a1 as l,A as a,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 上操作目录 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上操作目录 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上操作目录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上操作目录 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180516 Manipulating Directories in Linux","title":"在 Linux 上操作目录","tag":"201809","desc":""},"relativePath":"201809/20180516 Manipulating Directories in Linux.md","filePath":"[post].md"}'),u={name:"201809/20180516 Manipulating Directories in Linux.md"};function g(h,e,k,c,m,b){const t=o("Link");return r(),p("div",null,[e[34]||(e[34]=s("h1",{id:"在-linux-上操作目录",tabindex:"-1"},[i("在 Linux 上操作目录 "),s("a",{class:"header-anchor",href:"#在-linux-上操作目录","aria-label":"Permalink to “在 Linux 上操作目录”"},"​")],-1)),e[35]||(e[35]=s("p",null,[s("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/branches-238379_1920_0.jpg?itok=2PlNpsVu",alt:""})],-1)),e[36]||(e[36]=s("blockquote",null,[s("p",null,"让我们继续学习一下 Linux 文件系统的树形结构，并展示一下如何在其中创建你的目录。")],-1)),s("p",null,[e[1]||(e[1]=i("如果你不熟悉本系列（以及 Linux），",-1)),l(t,{href:"https://linux.cn/article-9798-1.html"},{default:a(()=>[...e[0]||(e[0]=[i("请查看我们的第一部分",-1)])]),_:1}),e[2]||(e[2]=i("。在那篇文章中，我们贯穿了 Linux 文件系统的树状结构（或者更确切地说是",-1)),e[3]||(e[3]=s("ruby",null,[i("文件层次结构标准"),s("rt",null,"File Hierarchy Standard")],-1)),e[4]||(e[4]=i("，FHS）。我建议你仔细阅读，确保你理解自己能安全的做哪些操作。因为这一次，我将向你展示目录操作的魅力。",-1))]),e[37]||(e[37]=n(`<h3 id="新建目录" tabindex="-1">新建目录 <a class="header-anchor" href="#新建目录" aria-label="Permalink to “新建目录”">​</a></h3><p>在破坏之前，先让我们来创建。首先，打开一个终端窗口并使用命令 <code>mkdir</code> 创建一个新目录，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir &lt;directoryname&gt;</span></span></code></pre></div><p>如果你只输入了目录名称，该目录将显示在您当前所在目录中。如果你刚刚打开一个终端，你当前位置为你的家目录。在这个例子中，我们展示了将要创建的目录与你当前所处位置的关系：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd # 告知你当前所在位置（参见第一部分）</span></span>
<span class="line"><span>/home/&lt;username&gt;</span></span>
<span class="line"><span>$ mkdir newdirectory # 创建 /home/&lt;username&gt;/newdirectory</span></span></code></pre></div><p>（注：你不用输入 <code>＃</code> 后面的文本。<code>#</code> 后面的文本为注释内容，用于解释发生了什么。它会被 shell 忽略，不会被执行）。</p><p>你可以在当前位置中已经存在的某个目录下创建新的目录，方法是在命令行中指定它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir Documents/Letters</span></span></code></pre></div><p>这将在 <code>Documents</code> 目录中创建 <code>Letters</code> 目录。</p><p>你还可以在路径中使用 <code>..</code> 在当前目录的上一级目录中创建目录。假设你进入刚刚创建的 <code>Documents/Letters/</code> 目录，并且想要创建<code>Documents/Memos/</code> 目录。你可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd Documents/Letters # 进入到你刚刚创建的 Letters/ 目录</span></span>
<span class="line"><span>mkdir ../Memos</span></span></code></pre></div><p>同样，以上所有内容都是相对于你当前的位置做的。这就是使用了相对路径。</p><p>你还可以使用目录的绝对路径：这意味着告诉 <code>mkdir</code> 命令将目录放在和根目录（<code>/</code>）有关的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir /home/&lt;username&gt;/Documents/Letters</span></span></code></pre></div><p>在上面的命令中将 <code>&lt;username&gt;</code> 更改为你的用户名，这相当于从你的主目录执行 <code>mkdir Documents/Letters</code>，通过使用绝对路径你可以在目录树中的任何位置完成这项工作。</p><p>无论你使用相对路径还是绝对路径，只要命令成功执行，<code>mkdir</code> 将静默的创建新目录，而没有任何明显的反馈。只有当遇到某种问题时，<code>mkdir</code>才会在你敲下回车键后打印一些反馈。</p><p>与大多数其他命令行工具一样，<code>mkdir</code> 提供了几个有趣的选项。 <code>-p</code> 选项特别有用，因为它允许你嵌套创建目录，即使目录不存在也可以。例如，要在 <code>Documents/</code> 中创建一个目录存放写给妈妈的信，你可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p Documents/Letters/Family/Mom</span></span></code></pre></div><p><code>mkdir</code> 会创建 <code>Mom/</code> 之上的整个目录分支，并且也会创建 <code>Mom/</code> 目录，无论其上的目录在你敲入该命令时是否已经存在。</p><p>你也可以用空格来分隔目录名，来同时创建几个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir Letters Memos Reports</span></span></code></pre></div><p>这将在当前目录下创建目录 <code>Letters</code>、<code>Memos</code> 和 <code>Reports</code>。</p><h3 id="目录名中可怕的空格" tabindex="-1">目录名中可怕的空格 <a class="header-anchor" href="#目录名中可怕的空格" aria-label="Permalink to “目录名中可怕的空格”">​</a></h3><p>……这带来了目录名称中关于空格的棘手问题。你能在目录名中使用空格吗？是的你可以。那么建议你使用空格吗？不，绝对不建议。空格使一切变得更加复杂，并且可能是危险的操作。</p><p>假设您要创建一个名为 <code>letters mom/</code> 的目录。如果你不知道如何更好处理，你可能会输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir letters mom</span></span></code></pre></div><p>但这是错误的！错误的！错误的！正如我们在上面介绍的，这将创建两个目录 <code>letters/</code> 和 <code>mom/</code>，而不是一个目录 <code>letters mom/</code>。</p><p>得承认这是一个小麻烦：你所要做的就是删除这两个目录并重新开始，这没什么大不了。</p>`,28)),s("p",null,[e[7]||(e[7]=i("可是等等！删除目录可是个危险的操作。想象一下，你使用图形工具",-1)),l(t,{href:"https://userbase.kde.org/Dolphin"},{default:a(()=>[...e[5]||(e[5]=[i("Dolphin",-1)])]),_:1}),e[8]||(e[8]=i(" 或 ",-1)),l(t,{href:"https://projects-old.gnome.org/nautilus/screenshots.html"},{default:a(()=>[...e[6]||(e[6]=[i("Nautilus",-1)])]),_:1}),e[9]||(e[9]=i(" 创建了目录 ",-1)),e[10]||(e[10]=s("code",null,"letters mom/",-1)),e[11]||(e[11]=i("。如果你突然决定从终端删除目录 ",-1)),e[12]||(e[12]=s("code",null,"letters mom",-1)),e[13]||(e[13]=i("，并且您在同一目录下有另一个名为 ",-1)),e[14]||(e[14]=s("code",null,"letters",-1)),e[15]||(e[15]=i(" 的目录，并且该目录中包含重要的文档，结果你为了删除错误的目录尝试了以下操作：",-1))]),e[38]||(e[38]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir letters mom</span></span></code></pre></div><p>你将会有删除目录 letters 的风险。这里说“风险”，是因为幸运的是<code>rmdir</code> 这条用于删除目录的指令，有一个内置的安全措施，如果你试图删除一个非空目录时，它会发出警告。</p><p>但是，下面这个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -Rf letters mom</span></span></code></pre></div><p>（注：这是删除目录及其内容的一种非常标准的方式）将完全删除 <code>letters/</code> 目录，甚至永远不会告诉你刚刚发生了什么。）</p><p><code>rm</code> 命令用于删除文件和目录。当你将它与选项 <code>-R</code>（递归删除）和 <code>-f</code>（强制删除）一起使用时，它会深入到目录及其子目录中，删除它们包含的所有文件，然后删除子目录本身，然后它将删除所有顶层目录中的文件，再然后是删除目录本身。</p><p><code>rm -Rf</code> 是你必须非常小心处理的命令。</p><p>我的建议是，你可以使用下划线来代替空格，但如果你仍然坚持使用空格，有两种方法可以使它们起作用。您可以使用单引号或双引号，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir &#39;letters mom&#39;</span></span>
<span class="line"><span>mkdir &quot;letters dad&quot;</span></span></code></pre></div><p>或者，你可以转义空格。有些字符对 shell 有特殊意义。正如你所见，空格用于在命令行上分隔选项和参数。 “分离选项和参数”属于“特殊含义”范畴。当你想让 shell 忽略一个字符的特殊含义时，你需要转义，你可以在它前面放一个反斜杠（<code>\\</code>）如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir letters\\ mom</span></span>
<span class="line"><span>mkdir letter\\ dad</span></span></code></pre></div><p>还有其他特殊字符需要转义，如撇号或单引号（<code>&#39;</code>），双引号（<code>“</code>）和＆符号（<code>＆</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir mom\\ \\&amp;\\ dad\\&#39;s\\ letters</span></span></code></pre></div><p>我知道你在想什么：如果反斜杠有一个特殊的含义（即告诉 shell 它必须转义下一个字符），这也使它成为一个特殊的字符。然后，你将如何转义转义字符（<code>\\</code>）？</p><p>事实证明，你转义任何其他特殊字符都是同样的方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir special\\\\characters</span></span></code></pre></div><p>这将生成一个名为 <code>special\\characters/</code> 的目录。</p><p>感觉困惑？当然。这就是为什么你应该避免在目录名中使用特殊字符，包括空格。</p><p>以防误操作你可以参考下面这个记录特殊字符的列表。（LCTT 译注：此处原文链接丢失。）</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><ul><li>使用 <code>mkdir &lt;directory name&gt;</code> 创建新目录。</li><li>使用 <code>rmdir &lt;directory name&gt;</code> 删除目录（仅在目录为空时才有效）。</li><li>使用 <code>rm -Rf &lt;directory name&gt;</code> 来完全删除目录及其内容 —— 请务必谨慎使用。</li><li>使用相对路径创建相对于当前目录的目录： <code>mkdir newdir</code>。</li><li>使用绝对路径创建相对于根目录(<code>/</code>)的目录: <code>mkdir /home/&lt;username&gt;/newdir</code>。</li><li>使用 <code>..</code> 在当前目录的上级目录中创建目录： <code>mkdir ../newdir</code>。</li><li>你可以通过在命令行上使用空格分隔目录名来创建多个目录: <code>mkdir onedir twodir threedir</code>。</li><li>同时创建多个目录时，你可以混合使用相对路径和绝对路径: <code>mkdir onedir twodir /home/&lt;username&gt;/threedir</code>。</li><li>在目录名称中使用空格和特殊字符真的会让你很头疼，你最好不要那样做。</li></ul><p>有关更多信息，您可以查看 <code>mkdir</code>、<code>rmdir</code> 和 <code>rm</code> 的手册:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir</span></span>
<span class="line"><span>man rmdir</span></span>
<span class="line"><span>man rm</span></span></code></pre></div><p>要退出手册页，请按键盘 <code>q</code> 键。</p><h3 id="下次预告" tabindex="-1">下次预告 <a class="header-anchor" href="#下次预告" aria-label="Permalink to “下次预告”">​</a></h3><p>在下一部分中，你将学习如何创建、修改和删除文件，以及你需要了解的有关权限和特权的所有信息!</p>`,26)),s("p",null,[e[17]||(e[17]=i("通过 Linux 基金会和 edX 免费提供的",-1)),l(t,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:a(()=>[...e[16]||(e[16]=[i("“Introduction to Linux”",-1)])]),_:1}),e[18]||(e[18]=i("课程了解有关Linux的更多信息。",-1))]),e[39]||(e[39]=s("hr",null,null,-1)),s("p",null,[e[20]||(e[20]=i("via: ",-1)),l(t,{href:"https://www.linux.com/blog/learn/2018/5/manipulating-directories-linux"},{default:a(()=>[...e[19]||(e[19]=[i("https://www.linux.com/blog/learn/2018/5/manipulating-directories-linux",-1)])]),_:1})]),s("p",null,[e[25]||(e[25]=i("作者：",-1)),l(t,{href:"https://www.linux.com/users/bro66"},{default:a(()=>[...e[21]||(e[21]=[i("Paul Brown",-1)])]),_:1}),e[26]||(e[26]=i(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[22]||(e[22]=[i("lujun9972",-1)])]),_:1}),e[27]||(e[27]=i(" 译者：",-1)),l(t,{href:"https://github.com/way-ww"},{default:a(()=>[...e[23]||(e[23]=[i("way-ww",-1)])]),_:1}),e[28]||(e[28]=i(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[24]||(e[24]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[31]||(e[31]=i("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[29]||(e[29]=[i("LCTT",-1)])]),_:1}),e[32]||(e[32]=i(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:a(()=>[...e[30]||(e[30]=[i("Linux中国",-1)])]),_:1}),e[33]||(e[33]=i(" 荣誉推出",-1))])])}const C=d(u,[["render",g]]);export{y as __pageData,C as default};
